/* Kanpai — tokens + componentes do design system "Kanpai" (v1), compartilhado por todas as páginas do site. */
:root {
  --surface-page: #F8F6F1; --surface-card: #FFFFFF; --surface-sage: #EAF2EC; --surface-sand: #F1ECE3; --surface-media: #D3E6DA;
  --forest-900: #0F2A22; --forest-800: #173A2F; --ink: #0F2A22; --ink-muted: #4C5E55; --ink-subtle: #55665E;
  --primary: #0B7A4B; --primary-hover: #075C38; --accent-italic: #1F7F57; --mint-400: #62C49E; --mint-300: #8FD6B6;
  --on-dark: #CFE3D9; --on-dark-muted: #B7D3C5; --line: #DCDFD6; --control-border: #93A79C;
  --font-sans: "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-serif: "Instrument Serif", Georgia, "Times New Roman", serif;
  --radius-sm: 14px; --radius-md: 20px; --radius-lg: 28px; --radius-xl: 32px; --radius-2xl: 40px; --radius-pill: 999px;
  --shadow-nav: 0 8px 28px rgba(15,42,34,0.10); --shadow-float: 0 18px 40px rgba(15,42,34,0.12);
  --shadow-bar: 0 24px 56px rgba(15,42,34,0.12); --shadow-cta: 0 10px 24px rgba(11,122,75,0.22); --shadow-offer: 0 24px 48px rgba(15,42,34,0.16);
}
.kp { font-family: var(--font-sans); color: var(--ink); background: var(--surface-page); font-size: 16px; line-height: 1.65; width: 100%; min-width: 0; }
.kp *, .kp *::before, .kp *::after { box-sizing: border-box; }
.kp a { color: var(--primary); }
.kp a:hover { color: var(--primary-hover); }
.kp :focus-visible { outline: 3px solid var(--primary); outline-offset: 3px; }

/* Layout */
.kp-wrap { max-width: 1120px; margin: 0 auto; padding-inline: 24px; }
.kp-wide { max-width: 1240px; margin: 0 auto; padding-inline: 16px; }
.kp-section { padding-top: 112px; }
.kp-row { display: flex; flex-wrap: wrap; gap: 48px; align-items: flex-start; }
.kp-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
.kp-crumbs { display: flex; flex-wrap: wrap; gap: 8px; font-size: 13px; color: var(--ink-subtle); }
.kp-crumbs a { color: var(--ink-subtle); text-decoration: none; }
.kp-crumbs a:hover { color: var(--primary); text-decoration: underline; }

/* Tipografia */
.kp-display { margin: 0; font-size: 64px; line-height: 1.03; font-weight: 500; letter-spacing: -0.03em; text-wrap: balance; }
.kp-h1 { margin: 0; font-size: 48px; line-height: 1.06; font-weight: 500; letter-spacing: -0.02em; text-wrap: balance; }
.kp-h2 { margin: 0; font-size: 34px; line-height: 1.1; font-weight: 500; letter-spacing: -0.015em; text-wrap: balance; }
.kp-h3 { margin: 0; font-size: 21px; line-height: 1.3; font-weight: 600; }
.kp-accent { font-family: var(--font-serif); font-style: italic; font-weight: 400; color: var(--accent-italic); font-size: 1.13em; }
.kp-on-dark .kp-accent { color: var(--mint-300); }
.kp-lead { margin: 0; font-size: 18px; line-height: 1.6; color: var(--ink-muted); max-width: 34em; }
.kp-body { margin: 0; color: var(--ink-muted); max-width: 40em; }
.kp-small { font-size: 14px; line-height: 1.5; color: var(--ink-subtle); }
.kp-serif { font-family: var(--font-serif); font-weight: 400; }

/* Botões */
.kp-btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 52px; padding: 0 26px; border: 0; border-radius: var(--radius-pill); font: 700 15px/1.2 var(--font-sans); text-decoration: none; cursor: pointer; }
.kp-btn--primary { background: var(--primary); color: #FFFFFF; }
.kp a.kp-btn--primary, .kp a.kp-btn--primary:hover { color: #FFFFFF; }
.kp-btn--primary:hover { background: var(--primary-hover); }
.kp-btn--hero { min-height: 56px; font-size: 16px;  }
.kp-btn--ghost { background: var(--surface-card); color: var(--ink); }
.kp a.kp-btn--ghost { color: var(--ink); }
.kp-btn--on-dark { background: var(--mint-400); color: var(--forest-900); }
.kp a.kp-btn--on-dark, .kp a.kp-btn--on-dark:hover { color: var(--forest-900); }
.kp-btn--on-dark:hover { background: var(--mint-300); }
.kp-btn:disabled { opacity: .45; cursor: not-allowed; }
.kp-link { font-weight: 700; font-size: 15px; color: var(--primary); }

/* Superfícies */
.kp-block { border-radius: var(--radius-2xl); padding: 88px clamp(20px, 4vw, 56px); }
.kp-card { border-radius: var(--radius-lg); padding: 32px; background: var(--surface-card); }
.kp-sage { background: var(--surface-sage); }
.kp-sand { background: var(--surface-sand); }
.kp-forest { background: var(--forest-900); color: #FFFFFF; }
.kp-forest-800 { background: var(--forest-800); color: #FFFFFF; }
.kp-media { background: var(--surface-media); border-radius: var(--radius-lg); display: flex; align-items: center; justify-content: center; text-align: center; color: var(--forest-900); font-size: 13px; font-weight: 600; padding: 24px; }
.kp-media--arch { border-radius: 999px 999px 36px 36px; }

/* Tags e selos */
.kp-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
.kp-tag { padding: 7px 14px; border-radius: var(--radius-pill); background: var(--surface-sage); color: var(--primary-hover); font-size: 13px; font-weight: 600; }
.kp-badge { display: inline-block; padding: 4px 10px; border-radius: var(--radius-pill); background: var(--forest-900); color: #FFFFFF; font-size: 11px; letter-spacing: 0.08em; font-weight: 700; }
.kp-badge--soon { background: var(--surface-sand); color: #4A3A26; }

/* Chips de filtro (botões) */
.kp-chip { min-height: 44px; padding: 0 18px; border-radius: var(--radius-pill); border: 0; font: 600 14px var(--font-sans); cursor: pointer; background: var(--surface-card); color: var(--ink); }
.kp-chip[aria-pressed="true"] { background: var(--forest-900); color: #FFFFFF; }

/* Acordeão e FAQ */
.kp-accordion { border-top: 1px solid var(--line); }
.kp-accordion details { border-bottom: 1px solid var(--line); padding: 24px 4px; }
.kp-accordion summary, .kp-faq summary { cursor: pointer; list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.kp-accordion summary::-webkit-details-marker, .kp-faq summary::-webkit-details-marker { display: none; }
.kp-accordion h3 { margin: 0; font-family: var(--font-serif); font-weight: 400; font-size: 32px; line-height: 1.15; }
.kp-plus { width: 36px; height: 36px; flex: none; border-radius: var(--radius-pill); background: var(--surface-sage); color: var(--primary); display: flex; align-items: center; justify-content: center; font-size: 18px; transition: transform .2s; }
details[open] > summary .kp-plus { transform: rotate(45deg); }
.kp-faq { display: flex; flex-direction: column; gap: 10px; }
.kp-faq details { background: var(--surface-card); border-radius: var(--radius-md); padding: 20px 24px; }
.kp-faq summary { font-size: 17px; font-weight: 600; }
.kp-faq p { margin: 12px 0 0; font-size: 15px; line-height: 1.7; color: var(--ink-muted); }

/* Formulários */
.kp-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.kp-field label, .kp-label { font-size: 13px; font-weight: 700; color: var(--ink); }
.kp-input { width: 100%; min-height: 50px; border-radius: var(--radius-sm); border: 1px solid var(--control-border); background: var(--surface-card); padding: 0 14px; font: 15px var(--font-sans); color: var(--ink); }
textarea.kp-input { padding: 14px; min-height: 120px; resize: vertical; }
.kp-hint { font-size: 13px; color: var(--ink-subtle); }
.kp-check { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; color: var(--ink-muted); }
.kp-check input { width: 20px; height: 20px; margin: 2px 0 0; accent-color: var(--primary); flex: none; }

/* Avisos e listas */
.kp-notice { font-size: 14px; line-height: 1.6; color: var(--ink-muted); max-width: 780px; margin: 0; }
.kp-notice strong { color: var(--ink); }
.kp-postlist a { text-decoration: none; color: var(--ink); display: flex; gap: 18px; align-items: center; padding: 18px 0; border-bottom: 1px solid var(--line); }
.kp-postlist a:last-child { border-bottom: 0; }
.kp-meta { font-size: 12px; font-weight: 600; color: var(--primary-hover); }
.kp-dl { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 20px; margin: 0; }
.kp-dl dt { font-size: 13px; color: var(--ink-subtle); }
.kp-dl dd { margin: 4px 0 0; font-weight: 700; font-size: 17px; }

/* Tabela de valores */
.kp-tablebox { overflow-x: auto; border-radius: var(--radius-lg); background: var(--surface-card); }
.kp-table { width: 100%; border-collapse: collapse; min-width: 640px; font-size: 15px; }
.kp-table th, .kp-table td { text-align: left; padding: 18px 24px; border-bottom: 1px solid var(--line); vertical-align: top; }
.kp-table thead th { font-size: 13px; color: var(--ink-subtle); font-weight: 700; }
.kp-table tbody tr:last-child td, .kp-table tbody tr:last-child th { border-bottom: 0; }
.kp-num { font-variant-numeric: tabular-nums; white-space: nowrap; }

/* Menu responsivo (barra flutuante + painel no mobile) */
.kp-bar { position: relative; max-width: 1120px; margin: 0 auto; background: #FFFFFF; border-radius: 999px; box-shadow: 0 8px 28px rgba(15,42,34,0.10); padding: 8px 8px 8px 22px; display: flex; gap: 8px 20px; align-items: center; justify-content: space-between; font-family: 'DM Sans', system-ui, sans-serif; }
.kp-bar__brand { display: flex; gap: 10px; align-items: center; text-decoration: none; color: #0F2A22; flex: none; }
.kp-bar__brand img { height: 30px; width: auto; display: block; }
.kp-bar__brand span { font-size: 16px; font-weight: 700; letter-spacing: 0.32em; color: #0F2A22; }
.kp-bar__nav { display: flex; flex-wrap: wrap; gap: 2px; font-size: 14px; font-weight: 500; }
.kp-bar__nav a { color: #0F2A22; text-decoration: none; padding: 10px 14px; border-radius: 999px; }
.kp-bar__nav a:hover { background: #EAF2EC; color: #075C38; }
.kp-bar__nav a[aria-current="page"] { background: #EAF2EC; color: #075C38; font-weight: 700; }
.kp-bar__end { display: flex; gap: 8px; align-items: center; flex: none; }
.kp-bar__cta { display: inline-flex; align-items: center; min-height: 44px; padding: 0 20px; border-radius: 999px; background: #0B7A4B; color: #FFFFFF !important; text-decoration: none; font-weight: 700; font-size: 14px; white-space: nowrap; }
.kp-bar__cta:hover { background: #075C38; }
.kp-menu { display: none; }
.kp-menu > summary { list-style: none; cursor: pointer; display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 16px; border-radius: 999px; background: #EAF2EC; color: #0F2A22; font-weight: 700; font-size: 14px; }
.kp-menu > summary::-webkit-details-marker { display: none; }
.kp-menu .kp-menu__close { display: none; }
.kp-menu[open] .kp-menu__open { display: none; }
.kp-menu[open] .kp-menu__close { display: block; }
.kp-menu[open] > summary { background: #0F2A22; color: #FFFFFF; }
.kp-menu__panel { position: absolute; left: 0; right: 0; top: calc(100% + 10px); z-index: 60; background: #FFFFFF; border-radius: 28px; box-shadow: 0 24px 56px rgba(15,42,34,0.18); padding: 12px; display: flex; flex-direction: column; gap: 4px; }
.kp-menu__panel nav { display: flex; flex-direction: column; }
.kp-menu__panel nav a { color: #0F2A22; text-decoration: none; font-size: 17px; font-weight: 600; padding: 14px 16px; border-radius: 16px; }
.kp-menu__panel nav a:hover, .kp-menu__panel nav a[aria-current="page"] { background: #EAF2EC; color: #075C38; }
.kp-menu__panel .kp-bar__cta { justify-content: center; min-height: 52px; font-size: 16px; margin-top: 6px; }
.kp-menu__note { font-size: 13px; color: #55665E; text-align: center; padding: 8px 0 4px; }
@media (max-width: 1080px) {
  .kp-bar { padding: 8px 8px 8px 18px; }
  .kp-bar__nav { display: none; }
  .kp-menu { display: block; }
}
@media (max-width: 520px) {
  .kp-bar__brand span { font-size: 14px; letter-spacing: 0.26em; }
  .kp-bar__end > .kp-bar__cta { display: none; }
}

@media (prefers-reduced-motion: reduce) { .kp-plus { transition: none; } }
@media (max-width: 640px) {
  .kp-display { font-size: 42px; }
  .kp-h1 { font-size: 34px; }
  .kp-h2, .kp-accordion h3 { font-size: 26px; }
  .kp-block { padding-block: 56px; border-radius: var(--radius-xl); }
  .kp-section { padding-top: 80px; }
  .kp-wrap { padding-inline: 20px; }
  .kp-gallery { grid-template-columns: 1fr 1fr !important; grid-auto-rows: 160px !important; }
  .kp-gallery > * { grid-column: auto !important; grid-row: auto !important; }
  .kp-gallery > :first-child, .kp-gallery > :last-child { grid-column: 1 / -1 !important; }
  .kp .kp-h1[style*="font-size: 52px"] { font-size: 34px !important; }
  .kp [style*="font-size: 40px; line-height: 1.1"] { font-size: 30px !important; }
  .kp [style*="height: 520px"], .kp [style*="height: 500px"], .kp [style*="height: 480px"] { height: 380px !important; }
  .kp [style*="height: 440px"], .kp [style*="height: 420px"] { height: 280px !important; }
  .kp .kp-table th, .kp .kp-table td { padding: 14px 16px; }
}

